// ---------------------------------------------------------------- game flow
async function startGame() {
  if (!audio.loaded) return;
  dom.start.classList.remove('show');
  dom.result.classList.remove('show');
  dom.pause.classList.remove('show');
  dom.hud.classList.remove('hidden');
  dom.hud.setAttribute('aria-hidden', 'false');
  document.body.classList.add('playing');
  resetGame();
  gameState = 'starting';
  try {
    await audio.start(0);
    gameState = 'playing';
    toast('LISTEN // 4 LANES', 1500);
  } catch (err) {
    console.error(err);
    gameState = 'menu';
    document.body.classList.remove('playing');
    dom.hud.classList.add('hidden');
    dom.start.classList.add('show');
    dom.startLabel.textContent = 'AUDIO ERROR';
    toast('AUDIO COULD NOT START', 3000);
  }
}

function pauseGame() {
  if (gameState !== 'playing') return;
  gameState = 'paused';
  audio.pause();
  dom.pause.classList.add('show');
}

async function resumeGame() {
  if (gameState !== 'paused') return;
  audio.resume();
  dom.pause.classList.remove('show');
  gameState = 'playing';
}

function quitToMenu() {
  gameState = 'menu';
  audio.stop();
  audio.resume();
  dom.pause.classList.remove('show');
  dom.result.classList.remove('show');
  dom.hud.classList.add('hidden');
  dom.hud.setAttribute('aria-hidden', 'true');
  dom.start.classList.add('show');
  document.body.classList.remove('playing');
  scene.setSection(CHART.sections[0]);
  for (const n of noteObjects) n.group.visible = false;
  held.fill(false);
  holdNote.fill(null);
  ghostCursor = 0;
  scene.clearGhosts();
  for (const p of dom.pads) p.classList.remove('pressed', 'active', 'sleep');
  document.documentElement.style.setProperty('--cyan', '#5ee7ff');
  document.documentElement.style.setProperty('--magenta', '#ff5fd2');
}

function finishGame() {
  if (gameState !== 'playing' && gameState !== 'paused') return;
  gameState = 'results';
  audio.stop();
  audio.resume();
  dom.hud.classList.add('hidden');
  dom.hud.setAttribute('aria-hidden', 'true');
  dom.pause.classList.remove('show');
  document.body.classList.remove('playing');

  const acc = stats.judged ? (stats.weight / stats.judged) * 100 : 100;
  let rank = 'D';
  if (acc >= 99.5) rank = 'S+';
  else if (acc >= 98) rank = 'S';
  else if (acc >= 93) rank = 'A';
  else if (acc >= 86) rank = 'B';
  else if (acc >= 76) rank = 'C';
  if (acc < 50) rank = 'F';
  if (stats.judged === 0) rank = 'F';

  const full = stats.miss === 0 && stats.bad === 0 && stats.judged > 0;

  const runScore = stats.score;
  const isBest = !personalBest
    || runScore > personalBest.score
    || (runScore === personalBest.score && acc > personalBest.acc);
  if (isBest) {
    personalBest = { score: runScore, acc, rank, maxCombo: stats.maxCombo, full, at: Date.now() };
    try { localStorage.setItem(BEST_KEY, JSON.stringify(personalBest)); } catch { /* storage unavailable */ }
  }
  renderBest();
  dom.bestBadge.classList.toggle('on', isBest);
  dom.bestNote.innerHTML = personalBest
    ? `BEST <b>${String(personalBest.score).padStart(7, '0')}</b> · ${personalBest.rank || '—'} · ${personalBest.acc.toFixed(2)}%`
    : '';

  dom.rank.textContent = rank;
  dom.finalScore.textContent = String(stats.score).padStart(7, '0');
  dom.finalAcc.textContent = acc.toFixed(2) + '%';
  dom.cPerfect.textContent = stats.perfect;
  dom.cGreat.textContent = stats.great;
  dom.cGood.textContent = stats.good;
  dom.cBad.textContent = stats.bad;
  dom.cMiss.textContent = stats.miss;
  dom.fMaxCombo.textContent = stats.maxCombo;
  dom.fcBadge.classList.toggle('on', full);
  dom.resultTag.textContent = full ? 'FULL COMBO // FIELD MASTERED'
    : acc < 50 ? 'SIGNAL LOST // TRY AGAIN'
    : 'CLEARED // SIGNAL COMPLETE';
  dom.result.classList.add('show');
}

function retryGame() {
  dom.result.classList.remove('show');
  startGame();
}

function alignPads() {
  // Tap zones sit exactly on the glowing lane rings, so the place you hit is
  // the place you press - there is no detached button row below the field.
  const points = scene.laneScreenPoints();
  const active = currentSection ? new Set(activeLanesFor(currentSection.keys)) : null;
  for (let i = 0; i < 8; i++) {
    const left = i > 0 ? points[i].x - points[i - 1].x : points[1].x - points[0].x;
    const right = i < 7 ? points[i + 1].x - points[i].x : points[7].x - points[6].x;
    const gap = Math.min(Math.abs(left), Math.abs(right));
    const size = Math.max(44, Math.min(148, gap * 1.02));
    const p = dom.pads[i];
    p.style.left = points[i].x.toFixed(1) + 'px';
    p.style.top = points[i].y.toFixed(1) + 'px';
    p.style.width = size.toFixed(1) + 'px';
    p.style.height = size.toFixed(1) + 'px';
    if (active) {
      const live = active.has(i);
      p.classList.toggle('sleep', !live);
      p.setAttribute('aria-hidden', String(!live));
    }
  }
}

function refreshSection(t) {
  const found = findSection(t);
  if (found.index !== sectionIndex || currentSection === null) {
    sectionIndex = found.index;
    updateSection(found.sec);
  }
}

function updateGhostEvents(t) {
  const list = CHART.ghosts || [];
  while (ghostCursor < list.length && list[ghostCursor].t <= t) {
    const g = list[ghostCursor++];
    scene.ghostFx(g.lane, g.type);
  }
}

