171: .pad{
172:   position:absolute;left:50%;top:50%;width:76px;height:76px;
173:   transform:translate(-50%,-50%);
174:   display:grid;place-items:center;
175:   padding:0;overflow:visible;
176:   border:1px solid transparent;border-radius:50%;
177:   background:transparent;
178:   transition:border-color .12s, background .12s, box-shadow .12s, opacity .25s, visibility .25s;
179:   touch-action:none;pointer-events:auto;
180: }
181: .pad::before{
182:   content:"";position:absolute;left:50%;bottom:-17px;width:16px;height:1px;
183:   transform:translateX(-50%);
184:   background:currentColor;opacity:0;transition:opacity .12s, width .12s;
