// Tiny CDP driver: opens the game, captures console errors, screenshots, and
// can exercise the track picker / start button with real input events.
import { writeFileSync } from 'node:fs';

const port = 9222;
const base = `http://127.0.0.1:${port}`;

async function get(path) {
  const r = await fetch(base + path);
  return r.json();
}

const targets = await get('/json/list');
let target = targets.find((t) => t.type === 'page');
if (!target) {
  const r = await fetch(base + '/json/new?http://localhost:3002/', { method: 'PUT' });
  target = await r.json();
}

const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

let id = 0;
const pending = new Map();
const logs = [];
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  } else if (msg.method === 'Runtime.consoleAPICalled') {
    logs.push(`console.${msg.params.type}: ` + msg.params.args.map((a) => a.value ?? a.description ?? '').join(' '));
  } else if (msg.method === 'Runtime.exceptionThrown') {
    logs.push('EXCEPTION: ' + (msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails.text));
  } else if (msg.method === 'Log.entryAdded') {
    logs.push(`log.${msg.params.entry.level}: ${msg.params.entry.text}`);
  }
};
function send(method, params = {}) {
  const mid = ++id;
  return new Promise((resolve, reject) => {
    pending.set(mid, { resolve, reject });
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

await send('Runtime.enable');
await send('Log.enable');
await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: 'http://localhost:3002/' });
await sleep(4500);

async function evalJs(expr) {
  const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
  return r.result?.value;
}
async function shot(path) {
  const r = await send('Page.captureScreenshot', { format: 'png' });
  writeFileSync(path, Buffer.from(r.data, 'base64'));
}

const info = await evalJs(`(() => ({
  state: window.__cryout?.state,
  chart: window.__cryout?.chart?.song,
  notes: window.__cryout?.notes?.length,
  startLabel: document.getElementById('startBtnLabel')?.textContent,
  startDisabled: document.getElementById('startBtn')?.disabled,
  cards: [...document.querySelectorAll('.track-card')].map(c => c.dataset.track + ':' + c.classList.contains('active')),
  err: window.__loadErr || null,
}))()`);
console.log('BOOT', JSON.stringify(info, null, 1));
await shot('/tmp/opencode/menu.png');

// select the world track through a real click
const worldRect = await evalJs(`(() => { const r = document.querySelector('.track-card[data-track="world"]').getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);
await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: worldRect.x, y: worldRect.y, button: 'left', clickCount: 1 });
await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: worldRect.x, y: worldRect.y, button: 'left', clickCount: 1 });
await sleep(3000);
const afterSelect = await evalJs(`(() => ({
  state: window.__cryout?.state,
  chart: window.__cryout?.chart?.song,
  notes: window.__cryout?.notes?.length,
  label: document.getElementById('startBtnLabel')?.textContent,
  disabled: document.getElementById('startBtn')?.disabled,
  hudTrack: document.getElementById('hudTrack')?.textContent,
}))()`);
console.log('SELECT WORLD', JSON.stringify(afterSelect, null, 1));
await shot('/tmp/opencode/menu-world.png');

console.log('LOGS', logs.slice(-30));
ws.close();

