const base = 'http://127.0.0.1:9222';
const target = (await (await fetch(base + '/json/list')).json()).find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map();
ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); } };
const send = (method, params = {}) => new Promise((resolve, reject) => { const mid = ++id; pending.set(mid, { resolve, reject }); ws.send(JSON.stringify({ id: mid, method, params })); });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const ev = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text); return r.result?.value; };
const click = async (x, y) => { await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 }); await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 }); };
const clickSel = async sel => { const p = await ev(`(() => { const r=document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`); await click(p.x, p.y); };
const info = async () => ev(`(() => { const c=document.querySelector('.track-card[data-track="cryout"]'); const r=c.getBoundingClientRect(); const el=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2); return {s:window.__cryout.state, track:window.__cryout.chart.song.shortTitle, start:document.getElementById('startScreen').className, pause:document.getElementById('pauseScreen').className, rect:[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)], top:el?.tagName+'#'+el?.id+'.'+el?.className, closest:el?.closest?.('.track-card')?.dataset?.track}; })()`);

await send('Runtime.enable'); await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await send('Emulation.setTouchEmulationEnabled', { enabled: false });
await send('Page.navigate', { url: 'http://localhost:3002/' });
await sleep(3500);
console.log('boot', await info());
await clickSel('.track-card[data-track="world"]'); await sleep(3000);
console.log('world selected', await info());
