await clickSel('#pauseBtn'); await sleep(1000);
console.log('paused', await info());
await clickSel('#quitBtn'); await sleep(1200);
console.log('quit -> menu', await info());
await clickSel('.track-card[data-track="cryout"]'); await sleep(2800);
console.log('cryout click result', await info());
ws.close();

