283: function judgeHit(note, offset) {
284:   const a = Math.abs(offset);
285:   let kind;
286:   if (a <= WIN.perfect) kind = 'perfect';
287:   else if (a <= WIN.great) kind = 'great';
288:   else if (a <= WIN.good) kind = 'good';
289:   else kind = 'bad';
290: 
291:   stats[kind]++;
292:   stats.judged++;
293:   stats.weight += WEIGHT[kind];
294:   stats.score += SCORE[kind];
295:   stats.health = Math.min(100, stats.health + (kind === 'perfect' ? 1.1 : kind === 'great' ? .8 : kind === 'good' ? .4 : -1.6));
296: 
297:   if (kind === 'bad') {
298:     setCombo(0, false);
299:   } else {
300:     setCombo(stats.combo + 1);
301:   }
302: 
303:   if (note.type === 'hold') {
304:     note.state = 'holding';
305:     note.endTime = note.data.t + note.data.dur;
306:     note.tickAt = audio.time;
307:     note.head.visible = false;
308:     holdNote[note.lane] = note;
309:   } else {
310:     note.state = 'done';
311:     note.group.visible = false;
312:   }
313: 
314:   const text = kind === 'perfect' ? 'PERFECT' : kind === 'great' ? 'GREAT' : kind === 'good' ? 'GOOD' : 'BAD';
315:   showJudge(kind, text);
316:   scene.hitFx(note.lane, kind);
317:   audio.click(note.lane, kind === 'perfect' ? 0.52 : 0.38);
318: }
