393: function updateNotes(t) {
394:   const ns = scene.noteScale;
395:   for (const n of noteObjects) {
396:     if (n.state === 'pending') {
397:       const y = (n.data.t - t) * SPEED;
398:       // local lane space: the lane frame supplies the diagonal world position
399:       n.group.position.set(0, y, 0.24);
400:       n.group.visible = y < 14.5 && y > -1.3;
401:       n.head.scale.set(1.04 * ns, 1.04 * ns, 1);
402:       if (n.body) {
403:         const len = n.data.dur * SPEED;
404:         n.body.visible = n.group.visible;
405:         n.tail.visible = n.group.visible;
406:         n.body.scale.set(0.52 * ns, len, 1);
407:         n.body.position.y = len / 2;
408:         n.body.material.rotation = -scene.laneScreenAngle(n.lane);
409:         n.tail.scale.set(0.68 * ns, 0.68 * ns, 1);
410:         n.tail.position.y = len;
411:       }
412:       if (t > n.data.t + HIT_WINDOW) missNote(n);
413:     } else if (n.state === 'holding') {
414:       if (!held[n.lane] && !touching()) { dropHold(n); continue; }
415:       if (t >= n.endTime - 0.02) {
416:         completeHold(n);
417:         continue;
418:       }
419:       const remain = Math.max(0, (n.endTime - t) * SPEED);
420:       n.group.visible = true;
421:       n.group.position.set(0, 0.02, 0.24);
422:       n.head.visible = false;
423:       if (n.body) {
424:         n.body.visible = remain > 0.03;
425:         n.body.scale.set(0.52 * ns, remain, 1);
426:         n.body.position.y = remain / 2;
427:         n.body.material.rotation = -scene.laneScreenAngle(n.lane);
428:         n.tail.visible = remain > 0.4;
429:         n.tail.scale.set(0.68 * ns, 0.68 * ns, 1);
430:         n.tail.position.y = remain;
431:       }
432:       if (t > n.tickAt) {
433:         n.tickAt = t + 0.12;
434:         stats.score += 24;
435:         stats.health = Math.min(100, stats.health + 0.06);
436:       }
437:     } else {
438:       n.group.visible = false;
439:     }
440:   }
441: }
