704:     p.style.left = g.x.toFixed(1) + 'px';
705:     p.style.top = bottom.toFixed(1) + 'px';
706:     p.style.width = width.toFixed(1) + 'px';
707:     p.style.height = height.toFixed(1) + 'px';
708:     p.style.transform = transform;
709:     const live = active.has(i);
710:     if (p.classList.contains('sleep') === live) p.classList.toggle('sleep', !live);
