const base = 'http://127.0.0.1:9222';
const target = (await (await fetch(base + '/json/list')).json()).find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const logs = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); }
  else if (m.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + (m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text));
};
const send = (method, params = {}) => new Promise((resolve, reject) => { const mid = ++id; pending.set(mid, { resolve, reject }); ws.send(JSON.stringify({ id: mid, method, params })); });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const ev = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text); return r.result?.value; };
const click = async (x, y) => { await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 }); await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 }); };
const clickSel = async sel => { const pt = await ev(`(() => { const r=document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`); await click(pt.x, pt.y); };

await send('Runtime.enable'); await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
await send('Page.navigate', { url: 'http://localhost:3002/' });
await sleep(3500);
await clickSel('.track-card[data-track="cryout"]'); await sleep(2600);
await clickSel('#startBtn'); await sleep(1800);
const setup = await ev(`(() => {
  const c = window.__cryout;
  const holds = c.chart.notes.filter(n => n.type === 'hold');
  const a = c.notes.find(n => n.data === holds[3]); // 64.135, lane 1
  const b = c.notes.find(n => n.data === holds[4]); // 65.335, lane 5
  a.state = 'holding'; b.state = 'holding';
  a.endTime = a.data.t + a.data.dur; b.endTime = b.data.t + b.data.dur;
  a.group.visible = true; b.group.visible = true;
  c.audio.startAt = c.audio.ctx.currentTime - 66.0;
  const fire = (lane, id, type) => {
    const el = document.querySelector('.pad[data-lane="' + lane + '"]');
    el.dispatchEvent(new PointerEvent(type, { pointerId: id, pointerType: 'touch', bubbles: true, cancelable: true, isPrimary: id === 11 }));
  };
  window.__fire = fire;
  fire(1, 11, 'pointerdown');
  fire(5, 12, 'pointerdown');
  return { a: a.state, b: b.state, t: +c.audio.time.toFixed(2) };
})()`);
await sleep(400);
const twoDown = await ev(`(() => { const c=window.__cryout; const hs=c.chart.notes.filter(n=>n.type==='hold'); const a=c.notes.find(n=>n.data===hs[3]); const b=c.notes.find(n=>n.data===hs[4]); return {a:a.state,b:b.state,t:+c.audio.time.toFixed(2),dropped:c.stats.dropped}; })()`);
await ev(`window.__fire(1, 11, 'pointerup')`);
await sleep(400);
const oneDown = await ev(`(() => { const c=window.__cryout; const hs=c.chart.notes.filter(n=>n.type==='hold'); const a=c.notes.find(n=>n.data===hs[3]); const b=c.notes.find(n=>n.data===hs[4]); return {a:a.state,b:b.state,t:+c.audio.time.toFixed(2),dropped:c.stats.dropped}; })()`);
await ev(`window.__fire(5, 12, 'pointerup')`);
await sleep(400);
const noneDown = await ev(`(() => { const c=window.__cryout; const hs=c.chart.notes.filter(n=>n.type==='hold'); const a=c.notes.find(n=>n.data===hs[3]); const b=c.notes.find(n=>n.data===hs[4]); return {a:a.state,b:b.state,t:+c.audio.time.toFixed(2),dropped:c.stats.dropped}; })()`);
console.log('SETUP', setup);
console.log('TWO FINGERS', twoDown);
console.log('ONE FINGER', oneDown);
console.log('NO FINGERS', noneDown);
console.log('LOGS', logs);
ws.close();

