#rank{
  font-size:clamp(90px,15vw,170px);line-height:.72;font-weight:900;letter-spacing:-.07em;
  color:#fff;text-shadow:0 0 40px rgba(94,231,255,.6),0 0 110px rgba(255,95,210,.35);
  font-style:italic;
}
.best-badge{
  display:none;font-family:var(--mono);font-size:8px;letter-spacing:.24em;
  color:#04040c;background:var(--cyan);padding:5px 10px;
  box-shadow:0 0 26px rgba(94,231,255,.45);
}
.best-badge.on{display:block;animation:bestPop .5s cubic-bezier(.2,.8,.2,1) both}
