.result-stats .bigstat{grid-column:span 2;padding:18px}
.result-stats .wide{grid-column:span 2}
.result-stats .bigstat b{font-size:clamp(24px,3vw,34px);color:#fff;text-shadow:0 0 22px rgba(94,231,255,.35)}
.result-foot{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}
.fc{
  font-family:var(--mono);font-size:9px;letter-spacing:.26em;color:var(--cyan);
