import { writeFileSync } from 'node:fs';
const base = 'http://127.0.0.1:9222';
const target = (await (await fetch(base + '/json/list')).json()).find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const logs = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); }
  else if (m.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + (m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text));
};
const send = (method, params = {}) => new Promise((resolve, reject) => { const mid = ++id; pending.set(mid, { resolve, reject }); ws.send(JSON.stringify({ id: mid, method, params })); });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const ev = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text); return r.result?.value; };
const click = async (x, y) => { await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 }); await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 }); };
const clickSel = async sel => { const pt = await ev(`(() => { const r=document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`); await click(pt.x, pt.y); };
const shot = async p => { const r = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync(p, Buffer.from(r.data, 'base64')); };

async function viewport(width, height, mobile) {
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: mobile ? 2 : 1, mobile });
  await send('Emulation.setTouchEmulationEnabled', { enabled: mobile, maxTouchPoints: 5 });
  await send('Page.navigate', { url: 'http://localhost:3004/' }); await sleep(3600);
}

await send('Runtime.enable'); await send('Page.enable');

// desktop start / world selection
await viewport(1440, 900, false);
await clickSel('.track-card[data-track="world"]'); await sleep(2800);
console.log('DESKTOP WORLD SELECT', await ev(`(() => { const c=document.querySelector('.track-card[data-track="world"]'); return {cs:getComputedStyle(c).borderColor, accent:getComputedStyle(c).getPropertyValue('--card-accent').trim(), arrow:getComputedStyle(document.querySelector('#startBtn i')).color, thumb:getComputedStyle(document.querySelector('.tc-tags .thumb')).backgroundColor}; })()`));
await shot('/tmp/opencode/v2-desktop-world-menu.png');

// mobile world menu
await viewport(390, 844, true);
await clickSel('.track-card[data-track="world"]'); await sleep(2800);
console.log('MOBILE WORLD SELECT', await ev(`(() => { const c=document.querySelector('.track-card[data-track="world"]'); const s=document.getElementById('startScreen'); return {border:getComputedStyle(c).borderColor, accent:getComputedStyle(c).getPropertyValue('--card-accent').trim(), fits:s.scrollHeight<=s.clientHeight+1, scroll:s.scrollHeight, client:s.clientHeight}; })()`));
await shot('/tmp/opencode/v2-mobile-world-menu.png');

// landscape results layout
await viewport(844, 390, true);
await clickSel('.track-card[data-track="world"]'); await sleep(2800);
await clickSel('#startBtn'); await sleep(1700);
await send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 20, y: 370, radiusX: 8, radiusY: 8, id: 1 }] });
await ev(`(() => { const c=window.__cryout; const notes=[...c.chart.notes].sort((a,b)=>a.t-b.t); for (const n of notes){ c.audio.startAt=c.audio.ctx.currentTime-n.t-0.004; c.pressLane(n.lane); } c.audio.startAt=c.audio.ctx.currentTime-(c.chart.song.chartEnd+0.05); })()`);
for (let i=0;i<100;i++){ if (await ev(`document.getElementById('resultScreen').classList.contains('show')`)) break; await sleep(80); }
await sleep(1400);
console.log('LANDSCAPE RESULT', await ev(`(() => { const box=document.querySelector('.results').getBoundingClientRect(); const screen=document.getElementById('resultScreen'); const retry=document.getElementById('retryBtn').getBoundingClientRect(); const menu=document.getElementById('menuBtn').getBoundingClientRect(); return {box:[Math.round(box.top),Math.round(box.bottom)], view:[innerWidth,innerHeight], scroll:[screen.scrollHeight,screen.clientHeight], retryInView:retry.top>=0&&retry.bottom<=innerHeight, menuInView:menu.top>=0&&menu.bottom<=innerHeight, scrollable:screen.scrollHeight>screen.clientHeight}; })()`));
await shot('/tmp/opencode/v2-landscape-results.png');
await send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
console.log('LOGS', logs);
ws.close();

