const ws=new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
let id=0;const p=new Map();const logs=[];
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&p.has(m.id)){const q=p.get(m.id);p.delete(m.id);m.error?q.reject(new Error(JSON.stringify(m.error))):q.resolve(m.result)}else if(m.method==='Runtime.exceptionThrown')logs.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)};
const send=(method,params={})=>new Promise((res,rej)=>{const mid=++id;p.set(mid,{resolve:res,reject:rej});ws.send(JSON.stringify({id:mid,method,params}))});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const ev=async x=>{const r=await send('Runtime.evaluate',{expression:x,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result?.value};
const click=async(x,y)=>{await send('Input.dispatchMouseEvent',{type:'mousePressed',x,y,button:'left',clickCount:1});await send('Input.dispatchMouseEvent',{type:'mouseReleased',x,y,button:'left',clickCount:1});};
const clickSel=async sel=>{const pt=await ev(`(() => { const r=document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);await click(pt.x,pt.y);};
const shot=async pb=>{const r=await send('Page.captureScreenshot',{format:'png'});writeFileSync(pb,Buffer.from(r.data,'base64'));};
await send('Runtime.enable');await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride',{width:844,height:390,deviceScaleFactor:2,mobile:true});
await send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:5});
await send('Page.navigate',{url:'http://localhost:3004/'});await sleep(3600);
await clickSel('.track-card[data-track="world"]');await sleep(2600);
await clickSel('#startBtn');await sleep(1700);
await send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:20,y:370,radiusX:8,radiusY:8,id:1}]});
await ev(`(() => { const c=window.__cryout; const notes=[...c.chart.notes].sort((a,b)=>a.t-b.t); for (const n of notes){ c.audio.startAt=c.audio.ctx.currentTime-n.t-0.004; c.pressLane(n.lane); } c.audio.startAt=c.audio.ctx.currentTime-(c.chart.song.chartEnd+0.05); })()`);
for(let i=0;i<100;i++){if(await ev(`document.getElementById('resultScreen').classList.contains('show')`))break;await sleep(80);}
await sleep(1400);
console.log(await ev(`(() => { const box=document.querySelector('.results').getBoundingClientRect(); const s=document.getElementById('resultScreen'); const retry=document.getElementById('retryBtn').getBoundingClientRect(); const menu=document.getElementById('menuBtn').getBoundingClientRect(); return {box:[Math.round(box.top),Math.round(box.bottom),Math.round(box.height)],view:[innerWidth,innerHeight],retry:[Math.round(retry.top),Math.round(retry.bottom)],menu:[Math.round(menu.top),Math.round(menu.bottom)],retryInView:retry.top>=0&&retry.bottom<=innerHeight,menuInView:menu.top>=0&&menu.bottom<=innerHeight,scrollable:s.scrollHeight>s.clientHeight,scroll:[s.scrollHeight,s.clientHeight]}; })()`));
await shot('/tmp/opencode/v3-landscape-results.png');
await send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
console.log('LOGS',logs);
ws.close();
EOF
