  for (let b = 1; b < bins; b++) {
    cur[b] = Math.sqrt(re[b] * re[b] + im[b] * im[b]);
    const hz = b * freqPerBin;
    if (hz < 160) sumLow += cur[b] * cur[b];
    else if (hz < 2400) sumMid += cur[b] * cur[b];
    else if (hz < 11000) sumHigh += cur[b] * cur[b];
