function buildChronostasis() {
 const bpm=99.4, beat=60/bpm, bar=beat*4, offset=0.323, step=beat/4;
 const rng=mulberry32(0x0c10c4a7);
 const peaks=[...chronoAnalysis.peaks].sort((a,b)=>a.t-b.t);
 const notes=[];
 const clockOrder={4:[0,3,1,2,2,1,3,0],6:[0,5,1,4,2,3,3,2,4,1,5,0]};
 const variant={...}
 chronoSections.forEach((sec,si)=>{
   const keys=sec.keys;
   const active=ACTIVE[keys];
   const startSlot=Math.ceil((Math.max(sec.start,sec.firstNote)-offset)/step-1e-6);
   const endSlot=Math.floor((sec.end-0.08-offset)/step-1e-6);
   let lastLane=-1,lastT=-99,slotIndex=0;
   for(let slot=startSlot;slot<=endSlot;slot++,slotIndex++){
     const t=offset+slot*step;
     const is16=slot%2===1;
     const isBeat=slot%4===0;
     const peak=nearestPeak(peaks,t,0.085);
     const strength=peak?peak.strength:0;
     let chance=sec.density;
     if(is16) chance*=0.38;
     if(sec.clock==='freeze'||sec.name==='STASIS') chance*=0.62;
     if(!peak && !isBeat){ chance*=0.25; }
     else if(strength<1.2 && !isBeat){ chance*=0.55; }
     if(rng()>chance) continue;
     // avoid off-grid pickups in quiet intro
     if(sec.name==='INTRO' && !isBeat && strength<1.8) continue;
     // choose lane from clock order / pendulum...
     let pos;
     const barSlot = slot%16;
     if(sec.name==='PENDULUM'){
       const order=[0,keys-1,1,keys-2,2,keys-3];
       pos=order[(Math.floor(slot/2)+ (is16?1:0))%order.length];
     } else if(sec.name==='GEARS'){
       const order=[0,keys-1,1,keys-2,2,keys-3];
       pos=order[Math.floor(slot/2)%order.length];
     } else {
       const order=clockOrder[keys];
       pos=order[Math.floor(slot/2)%order.length];
     }
     // small deterministic variation every other bar
     if (Math.floor(slot/8)%2===1 && keys>4) pos=(pos+1)%keys;
     let lane=lanePos(keys,pos);
     if(lane===lastLane && t-lastT<beat*0.72){
