+  scene.swingResolve(note.index, 'miss');
+  audio.thud();
+}
+
+function updateSwing(t) {
+  if (!swingMode) return;
+  for (const n of swingNotes) {
+    if (n.state === 'pending' && t > n.t + HIT_WINDOW) missSwing(n);
+  }
+}
