+function swingTap() {
+  if (gameState !== 'playing' || !swingMode) return;
+  const t = audio.time;
+  let best = null;
+  let bestAbs = Infinity;
+  for (const n of swingNotes) {
+    if (n.state !== 'pending') continue;
+    const d = t - n.t;
+    if (d < -EARLY_WINDOW || d > HIT_WINDOW) continue;
+    const a = Math.abs(d);
+    if (a < bestAbs) { bestAbs = a; best = n; }
+  }
+  if (!best) {
+    scene.swingWhiff();
+    audio.click(3, 0.1);
