input.command:
cd /tmp/opencode && cat > previewcheck.mjs <<'EOF'
const base='http://127.0.0.1:9222';
const target=await (async()=>{const l=await (await fetch(base+'/json/list')).json();return l.find(t=>t.type==='page');})();
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
let id=0;const p=new Map();const logs=[];
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&p.has(m.id)){const q=p.get(m.id);p.delete(m.id);m.error?q.reject(new Error(JSON.stringify(m.error))):q.resolve(m.result)}else if(m.method==='Runtime.exceptionThrown')logs.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)};
const send=(method,params={})=>new Promise((res,rej)=>{const mid=++id;p.set(mid,{resolve:res,reject:rej});ws.send(JSON.stringify({id:mid,method,params}))});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const ev=async x=>{const r=await send('Runtime.evaluate',{expression:x,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result?.value};
const click=async(x,y)=>{await send('Input.dispatchMouseEvent',{type:'mousePressed',x,y,button:'left',clickCount:1});await send('Input.dispatchMouseEvent',{type:'mouseReleased',x,y,button:'left',clickCount:1});};
const clickSel=async sel=>{const pt=await ev(`(() => { const r=document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);await click(pt.x,pt.y);};
await send('Runtime.enable');await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
await send('Emulation.setTouchEmulationEnabled',{enabled:false});
await send('Page.navigate',{url:'http://127.0.0.1:3005/'});await sleep(3400);
console.log('menu', await ev(`({tracks:document.querySelectorAll('.track-card').length,ready:!document.getElementById('startBtn').disabled,err:document.getElementById('toast').textContent})`));
await clickSel('.track-card[data-track="chronostasis"]');await sleep(2200);
await clickSel('#startBtn');await sleep(1600);
const pre=await ev(`({state:window.__cryout.state,track:window.__cryout.chart.song.title,swings:window.__cryout.swings.length,notes:window.__cryout.notes.length})`);
await ev(`(()=>{const c=window.__cryout;c.audio.startAt=c.audio.ctx.currentTime-66.9;})()`);
await sleep(700);
const post=await ev(`({swing:window.__cryout.swingMode,sec:document.getElementById('sectionName').textContent,pad:document.getElementById('centerPad').className,pend:window.__cryout.scene.pendulum.active,toast:document.getElementById('toast').textContent})`);
console.log({pre,post,logs});
ws.close();
EOF
node previewcheck.mjs 2>&1 | tail -20

